Mesh<Point, double> mesh;
for (RT::Finite_edges_iterator e_it = rt.finite_edges_begin(); e_it != rt.finite_edges_end(); ++e_it) {
    if (is_small_edge(rt, *e_it, threshold)) continue;

    RT::Cell_handle c1 = e_it->first->cell();
    RT::Cell_handle c2 = e_it->second->cell();

    if (c1->is_infinite() || c2->is_infinite()) continue;

    std::vector<Point> face_vertices;
    std::vector<RT::Cell_handle> cells = {c1, c2};

    // Collect all incident cells to form the face
    while (!cells.empty()) {
        RT::Cell_handle current = cells.back();
        cells.pop_back();

        for (int i = 0; i < 4; ++i) {
            RT::Cell_handle neighbor = current->neighbor(i);
            if (neighbor && !neighbor->is_infinite()) {
                bool found = false;
                for (auto& cell : cells) {
                    if (cell == neighbor) {
                        found = true;
                        break;
                    }
                }
                if (!found) {
                    cells.push_back(neighbor);
                }
            }
        }

        // Add vertices of the current cell to the face
        for (int i = 0; i < 4; ++i) {
            RT::Vertex_handle v = current->vertex(i);
            if (v->point() != Point::ORIGIN) {
                face_vertices.push_back(v->point());
            }
        }
    }

    // Remove duplicate vertices
    std::sort(face_vertices.begin(), face_vertices.end());
    auto last = std::unique(face_vertices.begin(), face_vertices.end());
    face_vertices.erase(last, face_vertices.end());

    // Calculate face area (or use squared_length as info)
    double area = 0.0;
    for (size_t i = 0; i < face_vertices.size(); ++i) {
        size_t j = (i + 1) % face_vertices.size();
        Vector v1 = face_vertices[i];
        Vector v2 = face_vertices[j];
        area += (v1.x() * v2.y() - v1.y() * v2.x());
    }
    area = std::abs(area) / 2.0;

    // Store the face
    std::vector<unsigned> indices;
    for (size_t i = 0; i < face_vertices.size(); ++i) {
        indices.push_back(i);
    }
    mesh.push_back(indices, area);
}

return mesh;

